import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int[][] a = new int[10][10];
    static int[][] ch = new int[70010][128];
    static int[][] q = new int[10][128];
    static int[][] dp = new int[10][70010];
    static Map<BitSet, Integer> id_map = new HashMap<>();
    static int id_count = 0;

    static int add_modulo(int x, int y) {
        x += y;
        if (x >= MOD) x -= MOD;
        return x;
    }

    static int mul_modulo(int x, int y) {
        long res = 1L * x * y;
        if (res >= MOD) res %= MOD;
        return (int) res;
    }

    static int sub_modulo(int x, int y) {
        x -= y;
        if (x < 0) x += MOD;
        return x;
    }

    static int pow_modulo(int base, int exp) {
        int res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = mul_modulo(res, base);
            base = mul_modulo(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int get_lowbit(int x) {
        return x & (-x);
    }

    static int dfs(BitSet s) {
        if (id_map.containsKey(s)) return id_map.get(s);
        id_map.put(s, ++id_count);
        for (int i = 0; i < (1 << n); i++) {
            BitSet tmp = (BitSet) s.clone();
            for (int j = 0; j < (1 << n); j++) {
                if (!tmp.get(j)) {
                    int x = i & j;
                    while (x != 0) {
                        int t = get_lowbit(x);
                        if (s.get(j ^ t)) {
                            tmp.set(j);
                            break;
                        }
                        x -= t;
                    }
                }
            }
            ch[id_map.get(s)][i] = dfs(tmp);
        }
        return id_map.get(s);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        BitSet initialSet = new BitSet(128);
        initialSet.set(0, 128);
        dfs(initialSet);
        for (int i = 0; i < n; i++) {
            String[] line = br.readLine().trim().split("\\s+");
            for (int j = 0; j < n; j++) {
                int val = Integer.parseInt(line[j]);
                a[i][j] = mul_modulo(val, pow_modulo(100, MOD - 2));
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                q[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) == 1) {
                        q[i][j] = mul_modulo(q[i][j], a[i][k]);
                    } else {
                        q[i][j] = mul_modulo(q[i][j], sub_modulo(1, a[i][k]));
                    }
                }
            }
        }
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], 0);
        }
        dp[0][1] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= id_count; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int index = ch[j][k];
                    dp[i][index] = add_modulo(dp[i][index], mul_modulo(dp[i - 1][j], q[i - 1][k]));
                }
            }
        }
        BitSet bits = new BitSet(128);
        bits.set(0, 128);
        int result = dp[n][id_map.get(bits)];
        System.out.println(result);
    }
}
